const API_BASE_URL = (typeof window !== "undefined" && window.SATAMONI_API_URL) || "http://localhost:4000";

const api = {
  async getFullConfig() {
    const res = await fetch(`${API_BASE_URL}/api/config/full`);
    if (!res.ok) throw new Error("تعذر تحميل بيانات الموقع من السيرفر");
    return res.json();
  },
  async createOrder(payload) {
    const res = await fetch(`${API_BASE_URL}/api/orders`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (!res.ok) throw new Error("تعذر إرسال الطلب، حاول مرة أخرى");
    return res.json();
  },
};

