export default function SatamoniOrdering() {
  const [site, setSite] = useState(null);
  const [cart, setCart] = useState({});
  const [cartOpen, setCartOpen] = useState(false);
  const [checkoutOpen, setCheckoutOpen] = useState(false);
  const [sizePicker, setSizePicker] = useState(null); // item currently choosing a size for
  const [favorites, setFavorites] = useState({});
  const [activeCat, setActiveCat] = useState(null);
  const [orderType, setOrderType] = useState("dinein");
  const [table, setTable] = useState("");
  const [selectedBranchId, setSelectedBranchId] = useState("");
  const [selectedAreaId, setSelectedAreaId] = useState("");
  const [addressDetails, setAddressDetails] = useState("");
  const [selectedPaymentId, setSelectedPaymentId] = useState("");
  const [locating, setLocating] = useState(false);
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [confirmed, setConfirmed] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [placedOrderId, setPlacedOrderId] = useState(null);
  const orderNumber = useOrderNumber();
  const sectionRefs = useRef({});
  const navRefs = useRef({});
  const scrollingProgrammatically = useRef(false);

  useEffect(() => {
    const init = (loaded) => {
      setSite(loaded);
      setActiveCat(Array.from(new Set(loaded.menu.map((m) => m.category)))[0]);
      setSelectedBranchId(loaded.branches[0]?.id || "");
      setSelectedAreaId(loaded.deliveryAreas[0]?.id || "");
      setSelectedPaymentId(loaded.paymentMethods.find((p) => p.enabled)?.id || "");
    };
    (async () => {
      // المحاولة الأولى: التحميل من الـ Backend المركزي (مصدر الحقيقة الحقيقي)
      try {
        const loaded = await api.getFullConfig();
        init(loaded);
        return;
      } catch (e) {
        console.warn("تعذر الاتصال بالسيرفر، هيتم عرض بيانات تجريبية محليًا:", e.message);
      }
      // احتياطي: لو السيرفر مش متاح (مثلاً أثناء التطوير)، استخدم بيانات محلية قديمة أو تجريبية
      try {
        const res = await window.storage.get(STORAGE_KEY, false);
        init(res ? JSON.parse(res.value) : FALLBACK);
      } catch (e) {
        init(FALLBACK);
      }
    })();
  }, []);

  const addItem = (item, variant) => {
    const key = `${item.id}__${variant.label}`;
    setCart((c) => ({
      ...c,
      [key]: {
        itemId: item.id,
        variantId: variant.id,
        name: item.name,
        label: variant.label,
        price: variant.price,
        qty: (c[key]?.qty || 0) + 1,
      },
    }));
  };
  const decItem = (key) => {
    setCart((c) => {
      const cur = c[key];
      if (!cur) return c;
      const qty = cur.qty - 1;
      const next = { ...c };
      if (qty <= 0) delete next[key];
      else next[key] = { ...cur, qty };
      return next;
    });
  };
  const qtyOf = (item, variant) => cart[`${item.id}__${variant.label}`]?.qty || 0;
  const totalQtyOf = (item) => item.variants.reduce((s, v) => s + qtyOf(item, v), 0);
  const toggleFavorite = (id) => setFavorites((f) => ({ ...f, [id]: !f[id] }));

  const handleAddClick = (item) => {
    if (item.variants.length > 1) {
      setSizePicker(item);
    } else {
      addItem(item, item.variants[0]);
    }
  };

  const cartList = useMemo(() => Object.entries(cart).map(([key, v]) => ({ key, ...v })), [cart]);
  const subtotal = cartList.reduce((s, i) => s + i.price * i.qty, 0);
  const cartCount = cartList.reduce((s, i) => s + i.qty, 0);

  const selectedArea = site?.deliveryAreas.find((a) => a.id === selectedAreaId);
  const deliveryFee = orderType === "delivery" && selectedArea ? selectedArea.fee : 0;
  const total = subtotal + deliveryFee;
  const belowMinOrder = orderType === "delivery" && selectedArea && selectedArea.minOrder > 0 && subtotal < selectedArea.minOrder;

  const canCheckout =
    cartList.length > 0 &&
    name.trim() &&
    phone.trim() &&
    selectedPaymentId &&
    !belowMinOrder &&
    (orderType !== "dinein" || (table.trim() && selectedBranchId)) &&
    (orderType !== "pickup" || selectedBranchId) &&
    (orderType !== "delivery" || (selectedAreaId && addressDetails.trim()));

  const findNearestBranch = () => {
    if (!site?.branches?.length) return;
    const withCoords = site.branches.filter((b) => b.lat && b.lng);
    if (withCoords.length === 0) {
      alert("لسه مفيش إحداثيات مضافة للفروع من لوحة التحكم، اختار الفرع يدويًا.");
      return;
    }
    setLocating(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        let best = withCoords[0];
        let bestDist = Infinity;
        withCoords.forEach((b) => {
          const d = haversine(latitude, longitude, Number(b.lat), Number(b.lng));
          if (d < bestDist) {
            bestDist = d;
            best = b;
          }
        });
        setSelectedBranchId(best.id);
        setLocating(false);
      },
      () => {
        setLocating(false);
        alert("مقدرناش نوصل لموقعك، اختار الفرع يدويًا من القايمة.");
      }
    );
  };

  const startNewOrder = () => {
    setCart({});
    setConfirmed(false);
    setSubmitError("");
    setPlacedOrderId(null);
    setCheckoutOpen(false);
    setCartOpen(false);
    setTable("");
    setAddressDetails("");
    setName("");
    setPhone("");
    setOrderType("dinein");
  };

  // إرسال الطلب فعليًا للـ Backend المركزي (بديل window.storage القديم)
  const submitOrder = async () => {
    setSubmitting(true);
    setSubmitError("");
    try {
      const payload = {
        branchId: orderType === "delivery" ? null : selectedBranchId,
        source: "website",
        orderType,
        tableNumber: orderType === "dinein" ? table : null,
        deliveryAreaId: orderType === "delivery" ? selectedAreaId : null,
        addressDetails: orderType === "delivery" ? addressDetails : null,
        customerName: name,
        customerPhone: phone,
        paymentMethodId: selectedPaymentId,
        deliveryFee,
        items: cartList.map((i) => ({
          itemId: i.itemId,
          variantId: i.variantId,
          unitPrice: i.price,
          quantity: i.qty,
        })),
      };
      const result = await api.createOrder(payload);
      setPlacedOrderId(result.orderId);
      setConfirmed(true);
    } catch (e) {
      setSubmitError(e.message || "حصل خطأ أثناء إرسال الطلب، حاول تاني.");
    } finally {
      setSubmitting(false);
    }
  };

  const scrollToCategory = (cat) => {
    scrollingProgrammatically.current = true;
    setActiveCat(cat);
    sectionRefs.current[cat]?.scrollIntoView({ behavior: "smooth", block: "start" });
    navRefs.current[cat]?.scrollIntoView({ behavior: "smooth", inline: "center", block: "nearest" });
    setTimeout(() => (scrollingProgrammatically.current = false), 700);
  };

  const handleScroll = useCallback(() => {
    if (scrollingProgrammatically.current || !site) return;
    const categories = Array.from(new Set(site.menu.map((m) => m.category)));
    let current = categories[0];
    for (const cat of categories) {
      const el = sectionRefs.current[cat];
      if (el && el.getBoundingClientRect().top - 170 <= 0) current = cat;
    }
    setActiveCat((prev) => (prev === current ? prev : current));
  }, [site]);

  useEffect(() => {
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, [handleScroll]);

  if (!site) {
    return (
      <div dir="rtl" lang="ar" style={{ background: COLORS.bg, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "'Cairo', sans-serif", color: COLORS.ink }}>
        <style>{FONTS}</style>
        <Loader2 className="animate-spin" size={20} />
        <span style={{ marginRight: "8px" }}>جاري تحميل المنيو...</span>
      </div>
    );
  }

  const categories = Array.from(new Set(site.menu.map((m) => m.category)));
  const enabledPayments = site.paymentMethods.filter((p) => p.enabled);
  const avgEta = Math.round(site.deliveryAreas.reduce((s, a) => s + a.etaMinutes, 0) / (site.deliveryAreas.length || 1)) || 25;

  return (
    <div dir="rtl" lang="ar" style={{ background: COLORS.bg, minHeight: "100vh", fontFamily: "'Cairo', sans-serif", color: COLORS.ink }}>
      <style>{FONTS}</style>

      {/* Hero banner */}
      <div style={{ position: "relative", height: "220px", overflow: "hidden" }}>
        <img src={HERO_SRC} alt="Satamoni" style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(14,14,16,0.15) 0%, rgba(14,14,16,0.9) 100%)" }} />
        <button
          onClick={() => setCartOpen(true)}
          style={{ position: "absolute", top: "16px", left: "16px", background: COLORS.red, color: "#fff", border: `1px solid ${COLORS.goldBright}`, borderRadius: "999px", padding: "9px 14px", display: "flex", alignItems: "center", gap: "8px", cursor: "pointer", fontFamily: "'Space Mono', monospace", fontSize: "13px", fontWeight: 700 }}
        >
          <ShoppingBag size={16} />
          {cartCount > 0 ? cartCount : ""}
        </button>
      </div>

      {/* Floating info card */}
      <div className="max-w-5xl mx-auto px-5" style={{ marginTop: "-64px", position: "relative", zIndex: 10 }}>
        <div style={{ background: COLORS.bgAlt, border: `1px solid ${COLORS.line}`, borderRadius: "16px", padding: "16px 18px", boxShadow: "0 10px 30px rgba(0,0,0,0.4)", display: "flex", alignItems: "center", justifyContent: "space-between", gap: "12px" }}>
          <div>
            <div style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "26px", color: COLORS.ink, lineHeight: 1 }}>ستاموني</div>
            <div style={{ color: COLORS.gold, fontSize: "10px", letterSpacing: "2px", marginTop: "4px", fontFamily: "'Space Mono', monospace" }}>SATAMONI</div>
          </div>
          <img src={LOGO_SRC} alt="" style={{ width: "58px", height: "58px", borderRadius: "50%", objectFit: "cover", border: `2px solid ${COLORS.gold}`, flexShrink: 0 }} />
        </div>
        <div style={{ background: COLORS.bgAlt, border: `1px solid ${COLORS.line}`, borderTop: "none", borderRadius: "0 0 16px 16px", padding: "12px 18px", display: "flex", justifyContent: "space-around", textAlign: "center", marginTop: "-10px", paddingTop: "18px" }}>
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "5px", color: COLORS.gold }}>
              <Clock size={14} />
              <span style={{ fontFamily: "'Space Mono', monospace", fontSize: "13px" }}>{avgEta} د</span>
            </div>
            <div style={{ fontSize: "11px", color: COLORS.faint, marginTop: "2px" }}>وقت التوصيل</div>
          </div>
          <div style={{ width: "1px", background: COLORS.line }} />
          <div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "5px", color: COLORS.gold }}>
              <MapPin size={14} />
              <span style={{ fontFamily: "'Space Mono', monospace", fontSize: "13px" }}>{site.branches.length}</span>
            </div>
            <div style={{ fontSize: "11px", color: COLORS.faint, marginTop: "2px" }}>فروع</div>
          </div>
          <div style={{ width: "1px", background: COLORS.line }} />
          <a href={`tel:${site.branches[0]?.phone}`} style={{ textDecoration: "none" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "5px", color: COLORS.gold }}>
              <Phone size={14} />
            </div>
            <div style={{ fontSize: "11px", color: COLORS.faint, marginTop: "2px" }}>اتصل بينا</div>
          </a>
        </div>
      </div>

      {/* Sticky category nav */}
      <div style={{ position: "sticky", top: 0, zIndex: 20, background: COLORS.bg, borderBottom: `1px solid ${COLORS.line}`, marginTop: "14px" }}>
        <nav className="max-w-5xl mx-auto px-5 py-3 flex gap-2 overflow-x-auto">
          {categories.map((c) => (
            <button
              key={c}
              ref={(el) => (navRefs.current[c] = el)}
              onClick={() => scrollToCategory(c)}
              style={{ whiteSpace: "nowrap", padding: "7px 18px", borderRadius: "999px", border: `1px solid ${activeCat === c ? COLORS.gold : COLORS.line}`, background: activeCat === c ? COLORS.gold : "transparent", color: activeCat === c ? "#1A1508" : COLORS.ink, fontSize: "14px", fontWeight: 700, cursor: "pointer" }}
            >
              {c}
            </button>
          ))}
        </nav>
      </div>

      {/* Menu — continuous scroll, list-style rows */}
      <main className="max-w-5xl mx-auto px-5 py-6">
        {categories.map((cat) => (
          <section key={cat} ref={(el) => (sectionRefs.current[cat] = el)} style={{ scrollMarginTop: "120px", marginBottom: "30px" }}>
            <h2 style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "22px", color: COLORS.goldBright, marginBottom: "14px" }}>{cat}</h2>
            <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
              {site.menu.filter((m) => m.category === cat).map((item) => {
                const qty = totalQtyOf(item);
                const single = item.variants.length === 1;
                return (
                  <div key={item.id} style={{ background: COLORS.card, border: `1px solid ${COLORS.cardBorder}`, borderRadius: "14px", padding: "12px", display: "flex", gap: "12px", alignItems: "center", position: "relative" }}>
                    {/* image */}
                    <div style={{ width: "84px", height: "84px", borderRadius: "10px", overflow: "hidden", flexShrink: 0, background: "#242024", display: "flex", alignItems: "center", justifyContent: "center" }}>
                      {item.image ? (
                        <img src={item.image} alt={item.name} style={{ width: "100%", height: "100%", objectFit: "cover" }} onError={(e) => (e.target.style.display = "none")} />
                      ) : (
                        <ChefHat size={26} color={COLORS.faint} />
                      )}
                      {item.best && (
                        <span style={{ position: "absolute", top: "6px", right: "6px", background: COLORS.gold, color: "#1A1508", fontSize: "9px", fontWeight: 800, padding: "2px 7px", borderRadius: "999px" }}>
                          الأكثر مبيعًا
                        </span>
                      )}
                    </div>

                    {/* content */}
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <h3 style={{ fontSize: "15px", fontWeight: 700, color: COLORS.ink, marginBottom: "3px" }}>{item.name}</h3>
                      {item.description && (
                        <p style={{ fontSize: "12px", color: COLORS.faint, marginBottom: "6px", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{item.description}</p>
                      )}
                      <div style={{ fontFamily: "'Space Mono', monospace", fontSize: "14px", fontWeight: 700, color: COLORS.goldBright }}>
                        {single ? money(item.variants[0].price) : `من ${money(Math.min(...item.variants.map((v) => v.price)))}`}
                      </div>
                    </div>

                    {/* controls */}
                    <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: "10px", flexShrink: 0 }}>
                      <button onClick={() => toggleFavorite(item.id)} style={{ background: "none", border: "none", cursor: "pointer", padding: 0 }} aria-label="مفضلة">
                        <Heart size={18} color={favorites[item.id] ? COLORS.red : COLORS.faint} fill={favorites[item.id] ? COLORS.red : "none"} />
                      </button>
                      {single && qty > 0 ? (
                        <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                          <button onClick={() => decItem(`${item.id}__${item.variants[0].label}`)} style={{ width: 26, height: 26, borderRadius: "50%", border: `1px solid ${COLORS.ink}`, background: "transparent", color: COLORS.ink, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
                            <Minus size={13} />
                          </button>
                          <span style={{ fontFamily: "'Space Mono', monospace", fontSize: "13px", minWidth: "12px", textAlign: "center" }}>{qty}</span>
                          <button onClick={() => addItem(item, item.variants[0])} style={{ width: 26, height: 26, borderRadius: "50%", border: "none", background: COLORS.red, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
                            <Plus size={13} />
                          </button>
                        </div>
                      ) : (
                        <button
                          onClick={() => handleAddClick(item)}
                          style={{ width: 32, height: 32, borderRadius: "50%", border: "none", background: COLORS.red, color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", position: "relative" }}
                        >
                          <Plus size={16} />
                          {qty > 0 && (
                            <span style={{ position: "absolute", top: "-6px", left: "-6px", background: COLORS.gold, color: "#1A1508", fontSize: "10px", fontWeight: 800, borderRadius: "50%", width: "16px", height: "16px", display: "flex", alignItems: "center", justifyContent: "center" }}>
                              {qty}
                            </span>
                          )}
                        </button>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </main>

      {/* Size picker popover */}
      {sizePicker && (
        <div style={{ position: "fixed", inset: 0, zIndex: 45, display: "flex", alignItems: "flex-end", justifyContent: "center" }}>
          <div onClick={() => setSizePicker(null)} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.6)" }} />
          <div style={{ position: "relative", width: "min(420px, 100%)", background: COLORS.bgAlt, borderRadius: "16px 16px 0 0", padding: "20px", border: `1px solid ${COLORS.line}`, borderBottom: "none" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "14px" }}>
              <h3 style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "20px" }}>{sizePicker.name}</h3>
              <button onClick={() => setSizePicker(null)} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.ink }}><X size={20} /></button>
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
              {sizePicker.variants.map((variant) => {
                const q = qtyOf(sizePicker, variant);
                const key = `${sizePicker.id}__${variant.label}`;
                return (
                  <div key={variant.label} style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "10px 12px", border: `1px solid ${COLORS.line}`, borderRadius: "10px" }}>
                    <div>
                      <div style={{ fontSize: "14px", fontWeight: 700 }}>{variant.label}</div>
                      <div style={{ fontFamily: "'Space Mono', monospace", fontSize: "13px", color: COLORS.goldBright }}>{money(variant.price)}</div>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                      {q > 0 && (
                        <>
                          <button onClick={() => decItem(key)} style={{ width: 28, height: 28, borderRadius: "50%", border: `1px solid ${COLORS.ink}`, background: "transparent", color: COLORS.ink, cursor: "pointer" }}>
                            <Minus size={14} />
                          </button>
                          <span style={{ fontFamily: "'Space Mono', monospace", minWidth: "14px", textAlign: "center" }}>{q}</span>
                        </>
                      )}
                      <button onClick={() => addItem(sizePicker, variant)} style={{ width: 28, height: 28, borderRadius: "50%", border: "none", background: COLORS.red, color: "#fff", cursor: "pointer" }}>
                        <Plus size={14} />
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
            <button onClick={() => setSizePicker(null)} style={{ marginTop: "16px", width: "100%", padding: "12px", background: COLORS.gold, color: "#1A1508", border: "none", borderRadius: "8px", fontWeight: 800, cursor: "pointer" }}>
              تم
            </button>
          </div>
        </div>
      )}

      {/* Cart drawer */}
      {cartOpen && (
        <div style={{ position: "fixed", inset: 0, zIndex: 30, display: "flex", justifyContent: "flex-start" }}>
          <div onClick={() => setCartOpen(false)} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.65)" }} />
          <div style={{ position: "relative", width: "min(380px, 100%)", background: COLORS.bgAlt, height: "100%", padding: "22px", overflowY: "auto", boxShadow: "8px 0 24px rgba(0,0,0,0.5)", borderInlineEnd: `1px solid ${COLORS.line}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "18px" }}>
              <h2 style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "26px", color: COLORS.ink }}>طلبك</h2>
              <button onClick={() => setCartOpen(false)} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.ink }}><X size={20} /></button>
            </div>

            {cartList.length === 0 ? (
              <p style={{ color: COLORS.faint, fontSize: "14px" }}>لسه مفيش أصناف. اختار من المنيو.</p>
            ) : (
              <div style={{ background: COLORS.card, border: `1px dashed ${COLORS.faint}`, borderRadius: "6px", padding: "16px", fontSize: "14px", color: COLORS.ink }}>
                {cartList.map((item) => (
                  <div key={item.key} style={{ display: "flex", justifyContent: "space-between", marginBottom: "10px", gap: "8px" }}>
                    <div style={{ flex: 1 }}>
                      <div>{item.name} {item.label !== "عادي" ? `(${item.label})` : ""}</div>
                      <div style={{ display: "flex", alignItems: "center", gap: "8px", marginTop: "4px" }}>
                        <button onClick={() => decItem(item.key)} style={{ width: 20, height: 20, border: `1px solid ${COLORS.ink}`, borderRadius: "50%", background: "none", color: COLORS.ink, cursor: "pointer" }}><Minus size={10} /></button>
                        <span style={{ fontFamily: "'Space Mono', monospace" }}>{item.qty}</span>
                        <button
                          onClick={() => setCart((c) => ({ ...c, [item.key]: { ...c[item.key], qty: c[item.key].qty + 1 } }))}
                          style={{ width: 20, height: 20, border: `1px solid ${COLORS.ink}`, borderRadius: "50%", background: "none", color: COLORS.ink, cursor: "pointer" }}
                        >
                          <Plus size={10} />
                        </button>
                      </div>
                    </div>
                    <div style={{ fontFamily: "'Space Mono', monospace", color: COLORS.goldBright }}>{money(item.price * item.qty)}</div>
                  </div>
                ))}
                <div style={{ borderTop: `1px dashed ${COLORS.faint}`, marginTop: "8px", paddingTop: "8px", fontFamily: "'Space Mono', monospace" }}>
                  <div style={{ display: "flex", justifyContent: "space-between" }}>
                    <span>الإجمالي الفرعي</span>
                    <span style={{ color: COLORS.goldBright }}>{money(subtotal)}</span>
                  </div>
                </div>
              </div>
            )}

            <button
              disabled={cartList.length === 0}
              onClick={() => { setCartOpen(false); setCheckoutOpen(true); }}
              style={{ marginTop: "18px", width: "100%", padding: "13px", background: cartList.length === 0 ? "#3A3630" : COLORS.red, color: "#fff", border: "none", borderRadius: "8px", fontWeight: 700, fontSize: "14px", cursor: cartList.length === 0 ? "not-allowed" : "pointer" }}
            >
              المتابعة للدفع
            </button>
          </div>
        </div>
      )}

      {/* Checkout modal */}
      {checkoutOpen && (
        <div style={{ position: "fixed", inset: 0, zIndex: 40, display: "flex", alignItems: "center", justifyContent: "center", padding: "16px" }}>
          <div onClick={() => !confirmed && setCheckoutOpen(false)} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.7)" }} />
          <div style={{ position: "relative", background: COLORS.bgAlt, border: `1px solid ${COLORS.line}`, borderRadius: "12px", width: "min(440px, 100%)", maxHeight: "88vh", overflowY: "auto", padding: "26px", color: COLORS.ink }}>
            {!confirmed ? (
              <>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "16px" }}>
                  <h2 style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "24px" }}>إتمام الطلب</h2>
                  <button onClick={() => setCheckoutOpen(false)} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.ink }}><X size={20} /></button>
                </div>

                <div style={{ display: "flex", gap: "8px", marginBottom: "16px" }}>
                  {[
                    { key: "dinein", label: "في المطعم", icon: UtensilsCrossed },
                    { key: "pickup", label: "استلام", icon: ShoppingBag },
                    { key: "delivery", label: "توصيل", icon: Bike },
                  ].map(({ key, label, icon: Icon }) => (
                    <button
                      key={key}
                      onClick={() => setOrderType(key)}
                      style={{ flex: 1, padding: "10px 6px", borderRadius: "8px", border: `1px solid ${orderType === key ? COLORS.gold : COLORS.line}`, background: orderType === key ? "#2A2308" : "transparent", display: "flex", flexDirection: "column", alignItems: "center", gap: "4px", cursor: "pointer", fontSize: "12px", fontWeight: 700, color: orderType === key ? COLORS.goldBright : COLORS.ink }}
                    >
                      <Icon size={16} />
                      {label}
                    </button>
                  ))}
                </div>

                {(orderType === "dinein" || orderType === "pickup") && (
                  <>
                    <Field label="الفرع">
                      <select value={selectedBranchId} onChange={(e) => setSelectedBranchId(e.target.value)} style={inputStyle}>
                        {site.branches.map((b) => (
                          <option key={b.id} value={b.id}>{b.name} — {b.address}</option>
                        ))}
                      </select>
                    </Field>
                    {orderType === "pickup" && (
                      <button type="button" onClick={findNearestBranch} disabled={locating} style={{ ...linkBtn, marginBottom: "12px" }}>
                        {locating ? <Loader2 size={14} className="animate-spin" /> : <Navigation size={14} />} استخدام موقعي لاختيار أقرب فرع
                      </button>
                    )}
                  </>
                )}

                {orderType === "dinein" && (
                  <Field label="رقم الطاولة">
                    <input value={table} onChange={(e) => setTable(e.target.value)} placeholder="مثال: 5" style={inputStyle} />
                  </Field>
                )}

                {orderType === "delivery" && (
                  <>
                    <Field label="منطقة التوصيل">
                      <select value={selectedAreaId} onChange={(e) => setSelectedAreaId(e.target.value)} style={inputStyle}>
                        {site.deliveryAreas.map((a) => (
                          <option key={a.id} value={a.id}>{a.name} — رسوم {a.fee} ج.م</option>
                        ))}
                      </select>
                    </Field>
                    {belowMinOrder && (
                      <p style={{ fontSize: "12px", color: "#F08A83", marginBottom: "10px" }}>أقل قيمة طلب لهذه المنطقة {selectedArea.minOrder} ج.م.</p>
                    )}
                    <Field label="تفاصيل العنوان">
                      <div style={{ position: "relative" }}>
                        <input value={addressDetails} onChange={(e) => setAddressDetails(e.target.value)} placeholder="الشارع، رقم العمارة، الدور" style={{ ...inputStyle, padding: "10px 34px 10px 10px" }} />
                        <MapPin size={16} style={{ position: "absolute", right: "10px", top: "18px", color: COLORS.faint }} />
                      </div>
                    </Field>
                  </>
                )}

                <Field label="الاسم">
                  <input value={name} onChange={(e) => setName(e.target.value)} placeholder="اسمك" style={inputStyle} />
                </Field>
                <Field label="رقم الموبايل">
                  <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="لتأكيد الطلب" style={inputStyle} />
                </Field>

                <Field label="طريقة الدفع">
                  <div style={{ display: "flex", flexDirection: "column", gap: "6px" }}>
                    {enabledPayments.map((p) => (
                      <label key={p.id} style={{ display: "flex", alignItems: "center", gap: "8px", padding: "8px 10px", border: `1px solid ${selectedPaymentId === p.id ? COLORS.gold : COLORS.line}`, borderRadius: "8px", cursor: "pointer" }}>
                        <input type="radio" name="pay" checked={selectedPaymentId === p.id} onChange={() => setSelectedPaymentId(p.id)} />
                        <span style={{ fontSize: "13px", fontWeight: 700 }}>{p.name}</span>
                        {p.note && <span style={{ fontSize: "11px", color: COLORS.faint, marginRight: "auto" }}>{p.note}</span>}
                      </label>
                    ))}
                  </div>
                </Field>

                <div style={{ fontFamily: "'Space Mono', monospace", fontSize: "14px", marginBottom: "16px", marginTop: "6px" }}>
                  <div style={{ display: "flex", justifyContent: "space-between" }}>
                    <span>الإجمالي الفرعي</span>
                    <span>{money(subtotal)}</span>
                  </div>
                  {deliveryFee > 0 && (
                    <div style={{ display: "flex", justifyContent: "space-between", color: COLORS.faint }}>
                      <span>رسوم التوصيل</span>
                      <span>{money(deliveryFee)}</span>
                    </div>
                  )}
                  <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 800, marginTop: "6px", color: COLORS.goldBright }}>
                    <span>الإجمالي</span>
                    <span>{money(total)}</span>
                  </div>
                </div>

                {submitError && (
                  <p style={{ fontSize: "12px", color: "#F08A83", marginBottom: "10px", textAlign: "center" }}>{submitError}</p>
                )}
                <button
                  disabled={!canCheckout || submitting}
                  onClick={submitOrder}
                  style={{ width: "100%", padding: "13px", background: canCheckout && !submitting ? COLORS.red : "#3A3630", color: "#fff", border: "none", borderRadius: "8px", fontWeight: 700, fontSize: "14px", cursor: canCheckout && !submitting ? "pointer" : "not-allowed", display: "flex", alignItems: "center", justifyContent: "center", gap: "8px" }}
                >
                  {submitting ? <Loader2 size={16} className="animate-spin" /> : <ChefHat size={16} />}
                  {submitting ? "جاري إرسال الطلب..." : "إرسال الطلب للمطبخ"}
                </button>
              </>
            ) : (
              <div style={{ textAlign: "center", padding: "12px 4px" }}>
                <div style={{ width: 56, height: 56, borderRadius: "50%", background: COLORS.gold, color: "#1A1508", display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
                  <Check size={28} />
                </div>
                <h2 style={{ fontFamily: "'Lalezar', sans-serif", fontSize: "26px", marginBottom: "6px" }}>تم إرسال الطلب!</h2>
                <p style={{ color: COLORS.faint, fontSize: "14px", marginBottom: "18px" }}>
                  {orderType === "dinein" ? "هنجهز طلبك ونجيبه للطاولة." : orderType === "pickup" ? "هنبعتلك رسالة لما يكون جاهز للاستلام." : "الطلب في الطريق إليك."}
                </p>
                <div style={{ border: `1px dashed ${COLORS.faint}`, borderRadius: "6px", padding: "16px", fontFamily: "'Space Mono', monospace", fontSize: "13px", textAlign: "right" }}>
                  <div style={{ display: "flex", justifyContent: "space-between" }}><span>رقم الطلب</span><span>{placedOrderId ? `#${placedOrderId}` : orderNumber}</span></div>
                  <div style={{ display: "flex", justifyContent: "space-between" }}><span>النوع</span><span>{orderType === "dinein" ? `طاولة ${table}` : orderType === "pickup" ? "استلام" : "توصيل"}</span></div>
                  {(orderType === "dinein" || orderType === "pickup") && (
                    <div style={{ display: "flex", justifyContent: "space-between" }}><span>الفرع</span><span>{site.branches.find((b) => b.id === selectedBranchId)?.name}</span></div>
                  )}
                  <div style={{ display: "flex", justifyContent: "space-between" }}><span>الدفع</span><span>{site.paymentMethods.find((p) => p.id === selectedPaymentId)?.name}</span></div>
                  <div style={{ display: "flex", justifyContent: "space-between", fontWeight: 800, marginTop: "6px", borderTop: `1px dashed ${COLORS.faint}`, paddingTop: "6px", color: COLORS.goldBright }}><span>الإجمالي</span><span>{money(total)}</span></div>
                </div>
                <button onClick={startNewOrder} style={{ marginTop: "20px", width: "100%", padding: "12px", background: "transparent", color: COLORS.goldBright, border: `1px solid ${COLORS.gold}`, borderRadius: "8px", fontWeight: 700, fontSize: "14px", cursor: "pointer" }}>
                  طلب جديد
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      <footer style={{ background: COLORS.bgAlt, borderTop: `1px solid ${COLORS.line}`, color: COLORS.faint, textAlign: "center", padding: "20px", fontSize: "13px" }}>
        <div style={{ display: "flex", flexDirection: "column", gap: "6px", alignItems: "center", marginBottom: "10px" }}>
          {site.branches.map((b) => (
            <div key={b.id} style={{ display: "flex", alignItems: "center", gap: "6px" }}><MapPin size={14} color={COLORS.gold} /> {b.address}</div>
          ))}
        </div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: "6px", fontFamily: "'Space Mono', monospace" }}>
          <Phone size={14} color={COLORS.gold} /> {site.branches[0]?.phone}
        </div>
      </footer>
    </div>
  );
}
